import { useState } from 'react'
import { FileDown } from 'lucide-react'
import { toast } from 'sonner'
import Button from '@/components/ui/Button.jsx'
import { downloadQuotationPdf } from '@/services/quotationService.js'
import { getErrorMessage } from '@/utils/errors.js'

/** Downloads one quotation version as a PDF (generated by /api/quotation-pdf). */
export default function DownloadPdfButton({ quotationId, versionId, label = 'Download PDF', variant = 'secondary', size = 'sm', className, disabled }) {
  const [busy, setBusy] = useState(false)

  async function download() {
    setBusy(true)
    try {
      await downloadQuotationPdf(quotationId, versionId)
    } catch (err) {
      toast.error(getErrorMessage(err))
    } finally {
      setBusy(false)
    }
  }

  return (
    <Button variant={variant} size={size} className={className} onClick={download} loading={busy} disabled={disabled}>
      {!busy && <FileDown className="size-4" aria-hidden="true" />}
      {busy ? 'Preparing PDF…' : label}
    </Button>
  )
}
